import numpy as np
from autograd import Tensor

x_plant = [0.5, -1.0, 0.8, 0.3, -0.4, 1.2]
p_plant = {'w': 0.7, 'u': 1.1, 'v': 0.9}


def num_grad(f, params, eps=1e-6):
    out = {}
    for k in params:
        up = dict(params); up[k] = params[k] + eps
        dn = dict(params); dn[k] = params[k] - eps
        out[k] = (f(up) - f(dn)) / (2 * eps)
    return out


def rel_err(a, b):
    worst = max(abs(a[k] - b[k]) for k in a)
    scale = max(1e-12, max(abs(v) for v in list(a.values()) + list(b.values())))
    return worst / scale


def ar_series(n, seed):
    e = np.random.default_rng(seed).standard_normal(n)
    x = np.empty(n)
    x[0] = e[0]
    for t in range(1, n):
        x[t] = 0.8 * x[t - 1] + e[t]
    return x.tolist()

